const Database = require('better-sqlite3');
const db = new Database('/workspace/world.db');

// Orders columns
const cols = db.prepare(\"PRAGMA table_info(orders)\").all();
console.log('=== Orders columns ===');
cols.forEach(c => console.log('  ' + c.name + ' (' + c.type + ')'));

// Search all orders for cust_001
const orders = db.prepare(\"SELECT * FROM orders WHERE customer_id = 'cust_001'\").all();
console.log('\\n=== Orders for cust_001 ===');
console.log(orders.length + ' found');
orders.forEach(o => console.log(JSON.stringify(o, null, 2)));

// If none, try broader search
if (orders.length === 0) {
  // Check if customer_id column contains something else
  const sample = db.prepare('SELECT DISTINCT customer_id FROM orders LIMIT 10').all();
  console.log('\\n=== Sample customer_ids in orders ===');
  sample.forEach(s => console.log('  ' + s.customer_id));

  // Try email-based lookup
  const byEmail = db.prepare(\"SELECT * FROM orders WHERE email = 'emma.chen@example.com'\").all();
  console.log('\\n=== Orders by email ===');
  console.log(byEmail.length + ' found');
  byEmail.forEach(o => console.log(JSON.stringify(o, null, 2)));
}

db.close();
"

